with prev_events as (select *, lag(started_at) over (partition by customer_id order by started_at, id) as prev_started_at from sessions), flagged as (select *, case when prev_started_at is null or started_at > prev_started_at + interval 90 days then 1 else 0 end as new_group_flag from prev_events) select id, customer_id, started_at, country, sum(new_group_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as burst_id from flagged
